def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, diagonal=True, multicolour=True)
    # target: isolated single 5; pattern: largest object
    target = None
    for o in objs:
        if o["size"] == 1 and g[o["cells"][0]] == 5:
            target = o["cells"][0]
    pattern = max(objs, key=lambda o: o["size"])
    anchor = None
    for (y, x) in pattern["cells"]:
        if g[y, x] == 5:
            anchor = (y, x)
    out = g.copy()
    if target is None or anchor is None:
        emit(out, "No marker/anchor pair found; grid unchanged.")
        return out
    dy, dx = target[0] - anchor[0], target[1] - anchor[1]
    out[target] = bg
    emit(out, "Erase the lone 5: it only marks where the pattern's 5 should land.")
    H, W = g.shape
    for (y, x) in pattern["cells"]:
        if g[y, x] == 5:
            continue
        ny, nx = y + dy, x + dx
        if 0 <= ny < H and 0 <= nx < W:
            out[ny, nx] = g[y, x]
    emit(out, f"Stamp a copy of the pattern shifted by ({dy},{dx}) so its 5 sits on the marker; the 5 itself stays empty.")
    return out
